        }
        StringTokenizer st = new StringTokenizer(sb.toString());
        int n = Integer.parseInt(st.nextToken());
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }

        // Altura final ótima: H = máximo inicial (só é possível aumentar).
        int H = 0;
        for (int i = 0; i < n; i++) if (a[i] > H) H = a[i];

        // Déficit de cada prédio: m[i] = H - a[i].
        // Cada fase atua num nível m = H - alturaCorrente e cobre exatamente,
        // com intervalos disjuntos, o conjunto {i : m[i] >= nivel}. Logo o número
        // mínimo de fases é soma, sobre todos os níveis, do número de blocos
        // contíguos maximais de {i : m[i] >= nivel}, o que equivale a:
        // resposta = m[0] + soma de max(0, m[i] - m[i-1])
        //          = (H - a[0]) + soma de max(0, a[i-1] - a[i]).
        long ans = H - a[0];
        for (int i = 1; i < n; i++) {
            if (a[i - 1] > a[i]) ans += a[i - 1] - a[i];
        }

        System.out.println(ans);
    }
